import{_ as e,o as a,c as r,a0 as i}from"./chunks/framework.D7EjqxMK.js";const c=JSON.parse('{"title":"Vibe Coding 概述","description":"","frontmatter":{},"headers":[],"relativePath":"07-ai-coding/02_vibe_coding/01_Vibe_Coding概述.md","filePath":"07-ai-coding/02_vibe_coding/01_Vibe_Coding概述.md"}'),n={name:"07-ai-coding/02_vibe_coding/01_Vibe_Coding概述.md"};function o(d,t,s,l,b,h){return a(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="vibe-coding-概述" tabindex="-1">Vibe Coding 概述 <a class="header-anchor" href="#vibe-coding-概述" aria-label="Permalink to &quot;Vibe Coding 概述&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块二 · 02_vibe_coding · 第 1 节 <strong>难度</strong>：⭐⭐⭐</p></blockquote><hr><h2 id="_1-起源" tabindex="-1">1. 起源 <a class="header-anchor" href="#_1-起源" aria-label="Permalink to &quot;1. 起源&quot;">​</a></h2><p><strong>Vibe Coding</strong> 一词由 <strong>Andrej Karpathy</strong>（OpenAI 联合创始人、Tesla AI 前总监）于 <strong>2025 年 2 月 2 日</strong>在 X 上发帖命名。<a href="https://vibecodelab.app/blog/what-is-vibecoding/" target="_blank" rel="noreferrer">来源: Karpathy 命名 (vibe.lab)</a></p><p>Karpathy 的帖子将一种新兴编程模式正式命名，迅速成为 2025 年 AI 编程领域最热门的话题。<a href="https://www.orbit.build/blog/what-is-vibe-coding" target="_blank" rel="noreferrer">来源: Vibe Coding 起源 (Orbit.build)</a></p><hr><h2 id="_2-概念" tabindex="-1">2. 概念 <a class="header-anchor" href="#_2-概念" aria-label="Permalink to &quot;2. 概念&quot;">​</a></h2><p><strong>Vibe Coding</strong> 是一种通过自然语言对话与 AI 交互的开发方式：开发者描述项目或任务，LLM 自动生成源码。<a href="https://en.wikipedia.org/wiki/Vibe_coding" target="_blank" rel="noreferrer">来源: Vibe coding (Wikipedia)</a></p><blockquote><p>Vibe Coding: &quot;Make this button bigger. Actually, move it left. No wait, make it a dropdown. Can you add a modal?&quot;</p><p>开发者：通过不断调整描述，让 AI 逐步逼近目标界面。</p></blockquote><h3 id="核心特征" tabindex="-1">核心特征 <a class="header-anchor" href="#核心特征" aria-label="Permalink to &quot;核心特征&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>对话式</strong></td><td>通过自然语言对话驱动开发</td></tr><tr><td><strong>迭代式</strong></td><td>不断调整描述，AI 逐步生成</td></tr><tr><td><strong>低门槛</strong></td><td>不需要深厚编程知识</td></tr><tr><td><strong>快速原型</strong></td><td>从想法到可运行代码极快</td></tr><tr><td><strong>创意自由</strong></td><td>开发者专注于设计意图而非代码语法</td></tr></tbody></table><hr><h2 id="_3-适用场景" tabindex="-1">3. 适用场景 <a class="header-anchor" href="#_3-适用场景" aria-label="Permalink to &quot;3. 适用场景&quot;">​</a></h2><h3 id="✅-最适合的场景" tabindex="-1">✅ 最适合的场景 <a class="header-anchor" href="#✅-最适合的场景" aria-label="Permalink to &quot;✅ 最适合的场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>理由</th></tr></thead><tbody><tr><td>快速原型 / POC</td><td>极速验证想法</td></tr><tr><td>MVP 开发</td><td>从 0 到 1 快速搭建</td></tr><tr><td>创意探索 / 设计迭代</td><td>通过对话探索 UI/UX</td></tr><tr><td>个人项目 / Side Project</td><td>无需团队协作</td></tr><tr><td>非关键业务脚本</td><td>Bug 风险可控</td></tr></tbody></table><h3 id="⚠️-不太适合的场景" tabindex="-1">⚠️ 不太适合的场景 <a class="header-anchor" href="#⚠️-不太适合的场景" aria-label="Permalink to &quot;⚠️ 不太适合的场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>原因</th></tr></thead><tbody><tr><td>生产代码</td><td>代码质量不可控</td></tr><tr><td>团队协作</td><td>缺乏明确的规格文档</td></tr><tr><td>复杂系统架构</td><td>缺乏系统性规划</td></tr><tr><td>长期维护项目</td><td>代码结构难以理解</td></tr><tr><td>安全敏感系统</td><td>代码安全审计困难</td></tr></tbody></table><hr><h2 id="_4-vibe-coding-的局限" tabindex="-1">4. Vibe Coding 的局限 <a class="header-anchor" href="#_4-vibe-coding-的局限" aria-label="Permalink to &quot;4. Vibe Coding 的局限&quot;">​</a></h2><p>2025 年 7 月，Business Insider 报道指出：&quot;Vibe coding is all the rage. But it has limits, forcing companies to impose parameters for its use.&quot; Vibe Coding 在企业级应用中遇到瓶颈，许多公司开始对其使用施加限制。<a href="https://www.businessinsider.com/vibe-coding-limits-use-cases-software-companies-airtable-redis-2025-7" target="_blank" rel="noreferrer">来源: Business Insider</a></p><p>Andrew Ng 也指出 Vibe Coding 是一个&quot;不恰当的术语&quot;（&quot;Unfortunate Term&quot;），他认为 coding with AI 是&quot;深度智力活动&quot;，不应被简化为&quot;凭感觉编程&quot;。<a href="https://www.businessinsider.com/andrew-ng-vibe-coding-unfortunate-term-exhausting-job-2025-6?op=1" target="_blank" rel="noreferrer">来源: Andrew Ng (Business Insider)</a></p><hr><h2 id="_5-vibe-coding-的学术定义" tabindex="-1">5. Vibe Coding 的学术定义 <a class="header-anchor" href="#_5-vibe-coding-的学术定义" aria-label="Permalink to &quot;5. Vibe Coding 的学术定义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>定义</th></tr></thead><tbody><tr><td><strong>Vibe coding: programming through conversation with AI (arXiv:2506.23253)</strong></td><td>&quot;Vibe coding 是一种通过与人工智能对话进行编程的方法。Advait Sarkar (Cambridge/UCL) 和 Ian Drosos (Microsoft Research) 提出。&quot; <a href="https://arxiv.org/html/2506.23253v2" target="_blank" rel="noreferrer">来源</a></td></tr><tr><td><strong>Vibe Coding: Toward an AI-Native Paradigm (arXiv:2510.17842)</strong></td><td>&quot;Recent advances in LLMs have enabled developers to generate software by conversing with AI systems rather than writing code.&quot; <a href="https://arxiv.org/pdf/2510.17842" target="_blank" rel="noreferrer">来源</a></td></tr></tbody></table><hr><h2 id="_6-vibe-coding-vs-vibe-coding-实践示例" tabindex="-1">6. Vibe Coding vs Vibe Coding 实践示例 <a class="header-anchor" href="#_6-vibe-coding-vs-vibe-coding-实践示例" aria-label="Permalink to &quot;6. Vibe Coding vs Vibe Coding 实践示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开发者: &quot;Build me a SaaS dashboard with auth, a database, and a chart&quot;</span></span>
<span class="line"><span>AI: [生成一个完整的 React 应用]</span></span>
<span class="line"><span>开发者: &quot;Make the chart blue and add a date picker&quot;</span></span>
<span class="line"><span>AI: [修改代码]</span></span>
<span class="line"><span>开发者: &quot;Add a user management page&quot;</span></span>
<span class="line"><span>AI: [添加页面]</span></span>
<span class="line"><span>... (通过对话迭代)</span></span></code></pre></div><hr><h2 id="_7-参考资料" tabindex="-1">7. 参考资料 <a class="header-anchor" href="#_7-参考资料" aria-label="Permalink to &quot;7. 参考资料&quot;">​</a></h2><ul><li><a href="https://en.wikipedia.org/wiki/Vibe_coding" target="_blank" rel="noreferrer">Vibe coding (Wikipedia)</a></li><li><a href="https://arxiv.org/html/2506.23253v2" target="_blank" rel="noreferrer">Vibe coding: programming through conversation with AI (arXiv:2506.23253)</a></li><li><a href="https://arxiv.org/pdf/2510.17842" target="_blank" rel="noreferrer">Vibe Coding: Toward an AI-Native Paradigm (arXiv:2510.17842)</a></li><li><a href="https://vibecodelab.app/blog/what-is-vibecoding/" target="_blank" rel="noreferrer">Karpathy 命名 Vibe Coding (vibe.lab)</a></li><li><a href="https://www.orbit.build/blog/what-is-vibe-coding" target="_blank" rel="noreferrer">Vibe Coding Origin (Orbit.build)</a></li><li><a href="https://www.businessinsider.com/andrew-ng-vibe-coding-unfortunate-term-exhausting-job-2025-6?op=1" target="_blank" rel="noreferrer">Andrew Ng: Vibe Coding Is an &#39;Unfortunate&#39; Term (Business Insider)</a></li><li><a href="https://www.ibm.com/think/topics/vibe-coding" target="_blank" rel="noreferrer">IBM: What is Vibe Coding?</a></li><li><a href="https://www.businessinsider.com/vibe-coding-limits-use-cases-software-companies-airtable-redis-2025-7" target="_blank" rel="noreferrer">Vibe Coding Is the Future. Just Don&#39;t Trust It. (Business Insider)</a></li><li><a href="https://codeinstitute.net/global/blog/what-is-vibe-coding-and-what-does-it-mean-for-real-coders/" target="_blank" rel="noreferrer">What is Vibe Coding and what does it mean for &quot;Real&quot; Coders? (Code Institute)</a></li><li><a href="https://cacm.acm.org/news/catching-the-vibe-of-vibe-coding/" target="_blank" rel="noreferrer">Catch the Vibe of Vibe Coding (ACM)</a></li><li><a href="https://tomkennes.com/blog/ai-assisted-coding-2/" target="_blank" rel="noreferrer">From Vibe Coding to Spec-Driven Development (tomkennes.com)</a></li></ul>`,31)])])}const p=e(n,[["render",o]]);export{c as __pageData,p as default};
